<!doctype html><html lang="en"><head>
<meta charset="utf-8">
<?php $this->load->view('comman/app_icons'); ?>
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title><?= htmlspecialchars($SITE_TITLE ?? 'MartPoint'); ?> — Conversation</title><link rel="stylesheet" href="<?= base_url('theme/css/font-awesome-4.7.0/css/font-awesome.min.css'); ?>"><style>
*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:#172033;font:15px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;padding-bottom:140px}.head{padding:15px 18px;background:#fff;border-bottom:1px solid #e4e8f0}.head .store{font-size:12px;color:#65728a;font-weight:700}.head h1{font-size:20px;margin:2px 0}.head a{color:#155eef;text-decoration:none;font-size:13px}.wrap{max-width:760px;margin:auto;padding:14px}.identity,.messages,.compose{background:#fff;border:1px solid #e1e7f0;border-radius:14px;padding:14px;margin-bottom:12px}.identity strong{display:block}.muted,.status{font-size:13px;color:#65728a}.messages{min-height:220px;max-height:55vh;overflow:auto;display:flex;flex-direction:column;gap:10px}.bubble{max-width:84%;padding:10px 12px;border-radius:14px;background:#f0f3f8;word-break:break-word}.outbound{align-self:flex-end;background:#155eef;color:#fff}.inbound{align-self:flex-start}.stamp{font-size:11px;color:#718099;margin-top:3px}.compose textarea{width:100%;min-height:90px;resize:vertical;border:1px solid #d9e0eb;border-radius:10px;padding:12px;font:inherit}.compose button{width:100%;margin-top:9px;background:#155eef;color:#fff;border:0;border-radius:10px;padding:12px;font:inherit;font-weight:700}
</style></head><body><header class="head"><div class="store"><?= htmlspecialchars($SITE_TITLE ?? 'MartPoint'); ?></div><a href="<?= base_url('online_store/messaging?screen=mobile&channel='.rawurlencode($conversation->channel)); ?>"><i class="fa fa-arrow-left"></i> Back to inbox</a><h1>Conversation</h1></header><main class="wrap"><section class="identity"><strong><?= htmlspecialchars($conversation->customer_name ?: ($conversation->customer_phone ?: 'Unknown customer')); ?></strong><span class="muted"><?= htmlspecialchars(ucfirst($conversation->channel)); ?> · <?= htmlspecialchars(ucfirst($conversation->status)); ?> · <?= htmlspecialchars($conversation->customer_phone ?: ''); ?></span></section><section class="messages" id="messages"><?php if(empty($messages)): ?><div class="muted">No messages yet.</div><?php else: foreach($messages as $m): ?><div class="bubble <?= $m->direction === 'outbound' ? 'outbound' : 'inbound'; ?>"><?= nl2br(htmlspecialchars($m->body ?: '(no text)')); ?><div class="stamp"><?= htmlspecialchars(ucfirst($m->direction).' · '.$m->created_at); ?></div></div><?php endforeach; endif; ?></section><form class="compose" id="reply-form"><input type="hidden" name="conversation_id" value="<?= (int)$conversation->id; ?>"><input type="hidden" name="<?= htmlspecialchars($this->security->get_csrf_token_name()); ?>" value="<?= htmlspecialchars($this->security->get_csrf_hash()); ?>"><label for="reply">Reply</label><textarea id="reply" name="text" maxlength="4000" placeholder="Write a reply…" required></textarea><button id="send" type="submit"><i class="fa fa-paper-plane"></i> Send reply</button><div class="status" id="status" role="status"></div></form></main><?php $this->load->view('mobile/bottom_nav',['active'=>'more']); ?><?php $this->load->view('mobile/chat'); ?><script>
(function(){var box=document.getElementById('messages'),form=document.getElementById('reply-form'),btn=document.getElementById('send'),status=document.getElementById('status');box.scrollTop=box.scrollHeight;form.addEventListener('submit',function(e){e.preventDefault();var text=document.getElementById('reply').value.trim();if(!text)return;btn.disabled=true;btn.textContent='Sending…';status.textContent='';fetch('<?= base_url('online_store/messaging_send'); ?>',{method:'POST',body:new FormData(form),credentials:'same-origin'}).then(function(r){return r.json()}).then(function(res){if(res.status==='success'){location.reload();}else{status.textContent=res.message||'Message could not be sent.';}}).catch(function(){status.textContent='Network error. Please retry.';}).finally(function(){btn.disabled=false;btn.innerHTML='<i class="fa fa-paper-plane"></i> Send reply';});});})();
</script></body></html>
